      const guidelineAnchors = ['cg-surg-10 applies', 'cg-surg-10 review', 'ambulatory or outpatient surgery center procedures guideline applies'];
      const trigger = bundle.documents.find((d) => keywordPresent(d.text, guidelineAnchors));
      if (!trigger) return { pass: true, evidence: 'Packet does not establish that Anthem CG-SURG-10 applies; rule vacuously satisfied.' };
      const rationaleAnchors = ['procedure complexity', 'anesthesia beyond local', 'sedation beyond local', 'enhanced monitoring', 'prolonged recovery', 'asa class iii', 'asa class iv', 'asa iii', 'asa iv', 'severe comorbidity', 'compromise the safety of an office', 'unsafe in an office setting'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, rationaleAnchors));
      if (!found) return { pass: false, note: 'Anthem packet says CG-SURG-10 applies (' + trigger.name + ') but does not document why an ambulatory or outpatient surgery-center facility is needed instead of an office.' };
