      const rationaleAnchors = ['requested site is medically necessary', 'requested location is medically necessary', 'higher acuity', 'requires hospital', 'monitoring unavailable', 'comorbidity requires', 'site exception', 'location exception'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, rationaleAnchors));
