      if (!trigger) return { pass: true, evidence: 'Packet is not an IBX Direct Ship general drug request; a J-code or specialty-drug mention alone is insufficient.' };
      const found = bundle.documents.find((d) => d.extract.icd10 && d.extract.icd10.length > 0);
      if (!found) return { pass: false, note: 'IBX Direct Ship general drug request (' + trigger.name + ') has no extracted ICD-10 diagnosis. Complete the form\'s required diagnosis field with the applicable ICD-10 code.' };
      return { pass: true, evidence: 'Direct Ship ICD-10 diagnosis in ' + found.name };
