      const eiAnchors = ['classified as experimental', 'classified as investigational', 'classified as experimental/investigational', 'experimental/investigational denial', 'experimental or investigational denial', 'ibx experimental determination', 'ibx investigational determination', 'phase i clinical trial', 'phase ii clinical trial', 'experimental arm of phase iii'];
      const trigger = bundle.documents.find((d) => keywordPresent(d.text, eiAnchors));
      if (!trigger) return { pass: true, evidence: 'Packet does not establish an IBX experimental/investigational classification; off-label or generic clinical-trial language alone is insufficient.' };
      const evidenceAnchors = ['reliable evidence', 'peer-reviewed', 'peer reviewed', 'authoritative medical literature', 'published evidence', 'positive effect on health outcomes', 'at least as effective', 'standard conditions of medical practice', 'fda approved for', 'fda-approved indication', 'compendia', 'ahfs', 'micromedex'];
