      const siteOfCareTrigger = bundle.documents.find((d) => keywordPresent(d.text, ['site of care required', 'site-of-care required', 'site of care management', 'site-of-care management']));
      if (!siteOfCareTrigger) return { pass: true, evidence: 'CareFirst packet does not identify a medical-drug site-of-care requirement; do not infer one from a procedure or J-code alone.' };
