      const trialAnchors = ['previous use', 'previously used', 'previously tried', 'prior drug', 'prior therapy', 'tried and failed', 'failed therapy', 'inadequate response', 'contraindication to', 'intolerance to', 'step therapy exception', 'step-therapy exception'];
