      const gapAnchors = ['reason for out-of-network request:', 'qualifying condition:', 'no network provider available', 'no participating provider', 'no in-network provider', 'network mismatch', 'lack of private transportation', 'unique services required', 'cannot safely transfer', 'language issues', 'other reason:'];
