      const clinicalAnchors = ['clinical documentation', 'progress note', 'clinical update', 'hospital course', 'current condition', 'response to treatment', 'plan of care', 'expected discharge'];
      const workflowAnchors = ['start continuation', 'continuation workflow started', 'continued stay submitted', 'continued-stay submitted'];
