      if (!trigger) return { pass: true, evidence: 'Packet does not name a Louisiana Blue drug authorization workflow; a J-code, injectable, or infusion alone does not trigger this advisory.' };
      const hasDiagnosis = bundle.documents.some((d) => d.extract.icd10 && d.extract.icd10.length > 0)
