      const requestAnchors = ['prior authorization', 'preauthorization', 'authorization request', 'prior approval'];
      const service = bundle.documents.find((d) => keywordPresent(d.text, serviceAnchors));
      const request = bundle.documents.some((d) => keywordPresent(d.text, requestAnchors));
      if (!service || !request) return { pass: true, evidence: 'No explicit Louisiana Blue DME or home-health authorization request; an E or K code alone does not trigger this advisory.' };
