      if (!found) return { pass: false, note: 'Illinois Medicaid service requires prior authorization (' + trigger.name + ') but no authorization / reference number is documented. Obtain authorization before the service date and record the reference number.' };
      return { pass: true, evidence: 'Authorization reference in ' + found.name };
