      if (!hasSurgeryCpt) return { pass: true, evidence: 'Illinois Medicaid packet without a surgical CPT; site-of-care rule vacuously satisfied.' };
      const hospitalSetting = bundle.documents.some((d) => d.extract.pos.includes('22') || d.extract.pos.includes('19'))
        || bundle.documents.some((d) => keywordPresent(d.text, ['hospital outpatient', 'outpatient hospital']));
      if (!hospitalSetting) return { pass: true, evidence: 'Illinois Medicaid surgery requested in an ASC / office setting; site-of-care rule vacuously satisfied.' };
      const rationaleAnchors = ['site of care', 'site-of-care', 'site of service', 'site-of-service', 'ambulatory surgical center', ' asc ', 'asa iii', 'asa iv', 'asa physical status', 'morbid obesity', 'higher acuity', 'requires hospital', 'hospital setting is medically necessary', 'medically necessary outpatient hospital'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, rationaleAnchors));
      if (!found) return { pass: false, note: 'Illinois Medicaid outpatient surgery is requested in a hospital-outpatient setting without a documented medical-necessity rationale for that site. The site-of-care policy expects an ASC / freestanding facility unless an exception is documented.' };
