      const appealAnchors = ['appeal', 'reconsideration', 'grievance', 'redetermination', 'fair hearing', 'state fair hearing', 'overturn the denial', 'dispute the determination'];
      const trigger = bundle.documents.find((d) => keywordPresent(d.text, appealAnchors));
