      const found = bundle.documents.find((d) => keywordPresent(d.text, refAnchors));
      if (!found) return { pass: false, note: 'New Jersey Medicaid service requires prior authorization (' + trigger.name + ') but no authorization / reference number is documented. Obtain authorization before the service date and record the reference number.' };
