      const authAnchors = ['prior authorization', 'preauthorization', 'authorization request', 'pa unit', 'pa request', 'authorization number', 'medical necessity', 'transplant evaluation'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, authAnchors));
